figure; %[output:9ea077d1]
plot(HAC_rd.BaG0_A(Pt),HAC_rd.Ba30_A(Pt),'.'); %[output:9ea077d1]

% fit between both data: slope 0.9575x+0.1082
fit_test=robustfit(HAC_rd.BaG0_A(Pt),HAC_rd.Ba30_A(Pt)); % y coor=0.0258, slope=0.9849, 1/slope=0.9251
